            restoreState();

            const ContentRenderer = {
                stickerMap: null, observer: null,
                init(targetNode) { this.loadStickers().then(() => { this.renderExisting(targetNode); this.startObserver(targetNode); }); },
                async loadStickers() { this.stickerMap = await StickerStorageManager.getStickers(); },
                renderNode(node) {
                    if (node.nodeType === Node.ELEMENT_NODE && node.classList.contains('message-content')) {
                        const imageRenderRegex = /<tp>([\s\S]*?)<\/tp>/g; const bqbRegex = /<bqb>(.*?)<\/bqb>/g; const voiceRegex = /<yy>([\s\S]*?)<\/yy>/g; const locationRegex = /<dw>(.*?)<\/dw>/g; const voiceIconSVG = `<svg class=\"voice-icon-svg\" viewBox=\"0 0 24 24\"><path d=\"M8,18.5C8,18.5 12,15.5 12,12C12,8.5 8,5.5 8,5.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\"/><path d=\"M12,20.5C12,20.5 16,16.5 16,12C16,7.5 12,3.5 12,3.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.6;\"/><path d=\"M4,15.5C4,15.5 8,13.5 8,12C8,10.5 4,8.5 4,8.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\" style=\"opacity: 0.8;\"/></svg>`;
                        let newHTML = node.innerHTML;
                        if (/^\s*<tp>[\s\S]*?<\/tp>\s*$/.test(newHTML.trim())) {
                            node.classList.add('has-image-card');
                        }
                        newHTML = newHTML.replace(imageRenderRegex, (match, imageDesc) => { const desc = imageDesc.trim().replace(/\n/g, '<br>'); const randomBg = `https://source.unsplash.com/random/120x120?sig=${Math.random()}`; return `<div class=\"image-card\" style=\"background-image: url('${randomBg}');\"><div class=\"image-card-desc\"><p>${desc}</p></div></div>`; });
                        newHTML = newHTML.replace(bqbRegex, (match, stickerName) => { const filename = this.stickerMap[stickerName]; return filename ? `<img src=\"${StickerStorageManager.URL_PREFIX + filename}\" class=\"sticker-preview\" alt=\"${stickerName}\" title=\"${stickerName}\">` : match; }); 
                        newHTML = newHTML.replace(voiceRegex, (match, voiceContent) => { const isSent = node.closest('.message.sent'); const contentText = voiceContent.trim(); const cleanedContentText = contentText.replace(/[（\(][\s\S]*?[）\)]/g, '').trim(); const duration = Math.max(1, Math.ceil(cleanedContentText.length / 6)); const durationSpan = `<span class=\"voice-duration\">${duration}\"</span>`; const barContent = isSent ? `${durationSpan}${voiceIconSVG}` : `${voiceIconSVG}${durationSpan}`; return `<div class=\"voice-message-container\"><button class=\"voice-bar\">${barContent}</button><div class=\"voice-transcription\">${contentText}</div></div>`; });
                        if (locationRegex.test(newHTML)) { node.classList.add('has-location-card'); newHTML = newHTML.replace(locationRegex, (match, locationText) => { return `<div class=\"location-card\"><div class=\"location-map\"><i class=\"fas fa-map-marker-alt\"></i></div><div class=\"location-info\"><p>${locationText.trim()}</p></div></div>`; }); }
                        node.innerHTML = newHTML;
                    }
                },
                renderExisting(targetNode) { targetNode.querySelectorAll('.message-content').forEach(content => this.renderNode(content)); },
                startObserver(targetNode) { this.observer = new MutationObserver(mutations => { mutations.forEach(mutation => { mutation.addedNodes.forEach(addedNode => { if (addedNode.nodeType === Node.ELEMENT_NODE) { if (addedNode.classList.contains('message')) { const content = addedNode.querySelector('.message-content'); if (content) this.renderNode(content); } else if (addedNode.querySelectorAll) { addedNode.querySelectorAll('.message-content').forEach(content => this.renderNode(content)); } } }); }); }); this.observer.observe(targetNode, { childList: true, subtree: true }); }
            };
            ContentRenderer.init(chatMessagesContainer);
            chatMessagesContainer.scrollTop = 0;

            chatMessagesContainer.addEventListener('click', (e) => {
                const imageCard = e.target.closest('.image-card'); if (imageCard) { imageCard.classList.toggle('show-desc'); return; }
                const voiceBar = e.target.closest('.voice-bar'); if (voiceBar) { const container = voiceBar.closest('.voice-message-container'); if (container) container.classList.toggle('active'); return; }
                const pokeBubble = e.target.closest('.poke-bubble'); if (pokeBubble) { container.classList.add('is-shaking'); setTimeout(() => container.classList.remove('is-shaking'), 500); }
            });

            stageBtn.addEventListener('click', stageUserTextMessage);
            textInput.addEventListener('keypress', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); stageUserTextMessage(); } });

            stagedMessagesDisplay.addEventListener('click', (e) => {
                const voiceBar = e.target.closest('.voice-bar');
                if (voiceBar) { const container = voiceBar.closest('.voice-message-container'); if (container) container.classList.toggle('active'); e.stopPropagation(); return; }

                if (e.target.classList.contains('delete-staged-msg-btn')) { 
                    const index = parseInt(e.target.dataset.index, 10); 
                    stagedMessages.splice(index, 1); 
                    persistState(); 
                    renderAllStagedMessages(); 
                    return; 
                }

                const clickedStagedMsg = e.target.closest('.message-staged');
                if (clickedStagedMsg) {
                    stagedMessagesDisplay.querySelectorAll('.message-staged.show-delete').forEach(el => {
                        if (el !== clickedStagedMsg) el.classList.remove('show-delete');
                    });
                    clickedStagedMsg.classList.toggle('show-delete');
                }
            });

            realSendBtn.addEventListener('click', () => sendStagedMessages());

            const stickerHandler = {
                init() {
                    this.renderAllStickers(); this.setupTabs(); this.setupAddPanel(); 
                    stickerMenuBtn.addEventListener('click', () => { actionMenu.style.display = 'none'; stickerPanel.classList.toggle('active'); });
                },
                createStickerItem(name, filename) { const url = StickerStorageManager.URL_PREFIX + filename; const item = document.createElement('div'); item.className = 'sticker-item'; item.innerHTML = `<img src=\"${url}\" alt=\"${name}\" title=\"${name}\">`; item.addEventListener('click', () => { stageMessage('sticker', { name: name, url: url }); stickerPanel.classList.remove('active'); }); item.addEventListener('contextmenu', async (e) => { e.preventDefault(); if (confirm(`删除表情 \"${name}\"?`)) { await StickerStorageManager.deleteSticker(name); this.renderAllStickers(); } }); return item; },
                async renderAllStickers() { const grid = container.querySelector('#all-stickers'); grid.innerHTML = ''; const stickers = await StickerStorageManager.getStickers(); for (const [name, filename] of Object.entries(stickers)) { grid.appendChild(this.createStickerItem(name, filename)); } },
                setupTabs() { container.querySelectorAll('.sticker-tab').forEach(tab => tab.addEventListener('click', () => { container.querySelectorAll('.sticker-tab, .sticker-grid, .sticker-add-panel').forEach(el => el.classList.remove('active')); const tabName = tab.dataset.tab; tab.classList.add('active'); container.querySelector(`#${tabName === 'add' ? 'add-sticker-panel' : 'all-stickers'}`).classList.add('active'); })); },
                setupAddPanel() { const urlInput = container.querySelector('#sticker-url-input'), nameInput = container.querySelector('#sticker-name-input'), preview = container.querySelector('#sticker-preview'); const updatePreview = () => { if (urlInput.value.trim()) preview.innerHTML = `<img src=\"${StickerStorageManager.URL_PREFIX + urlInput.value.trim()}\" style=\"max-width:100%;max-height:100%;\">`; }; urlInput.addEventListener('input', updatePreview);
                    container.querySelector('#add-sticker-btn').addEventListener('click', async () => { if (urlInput.value && nameInput.value) { await StickerStorageManager.addSticker(nameInput.value, urlInput.value); urlInput.value = ''; nameInput.value = ''; preview.innerHTML = ''; this.renderAllStickers(); container.querySelector('[data-tab=\"stickers\"]').click(); } });
                    container.querySelector('#cancel-add-sticker').addEventListener('click', () => { container.querySelector('[data-tab=\"stickers\"]').click(); });
                }
            };
            stickerHandler.init();

            function setupModal(button, overlay, onConfirm) { 
                if (!button || !overlay) return; 
                const modal = overlay.querySelector('.modal-box'); 
                const confirmBtn = modal.querySelector('.confirm'); 
                const cancelBtn = modal.querySelector('.cancel'); 
                button.addEventListener('click', () => { overlay.style.display = 'flex'; }); 
                cancelBtn.addEventListener('click', () => { overlay.style.display = 'none'; }); 
                overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.style.display = 'none'; }); 
                if(onConfirm) confirmBtn.addEventListener('click', () => onConfirm(modal, overlay)); 
            }
            setupModal(imageMenuBtn, imageModalOverlay, (modal, overlay) => { const textarea = modal.querySelector('.image-modal-textarea'); const desc = textarea.value.trim(); if (desc) { stageMessage('image', desc); textarea.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none'; } });
            setupModal(voiceMenuBtn, voiceModalOverlay, (modal, overlay) => { const textarea = modal.querySelector('.voice-modal-textarea'); const desc = textarea.value.trim(); if (desc) { stageMessage('voice', desc); textarea.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none';} });
            setupModal(locationMenuBtn, locationModalOverlay, (modal, overlay) => { const input = modal.querySelector('.location-modal-input'); const location = input.value.trim(); if (location) { stageMessage('location', location); input.value = ''; overlay.style.display = 'none'; actionMenu.style.display = 'none';} });

            plusBtn.addEventListener('click', () => { 
                stickerPanel.classList.remove('active');
                actionMenu.style.display = actionMenu.style.display === 'grid' ? 'none' : 'grid'; 
            });

            document.addEventListener('click', (e) => { 
                const isClickInsideModal = allModals.some(modal => modal.contains(e.target));
                if (!container.querySelector('.chat-input').contains(e.target) && !actionMenu.contains(e.target) && !stickerPanel.contains(e.target) && !isClickInsideModal) { 
                    actionMenu.style.display = 'none'; 
                    stickerPanel.classList.remove('active'); 
                } 
            });

            updateStatusTime();
            setInterval(updateStatusTime, 30000);
        });
    }, 100);
